insert into public.articles (id, slug, title, excerpt, body, topic, read_minutes, author, published_at, color_key) values
  ('a1', 'kangaroo-care-at-home', 'Kangaroo care: how to keep it going at home', 'Skin-to-skin does not stop when you leave the ward. Here is how to build it into an ordinary day.', 'Kangaroo care means holding your baby upright against your bare chest, with a blanket or wrap over both of you. Research consistently links it to steadier heart rates, better temperature control and easier feeding.
insert into public.policies (key, title, updated, body) values
  ('privacy', 'Privacy policy', '1 July 2026', 'Ibibondo collects only what it needs to fulfil an order: your name, phone number, delivery address, and the items you’ve bought. We never sell or share this information with anyone outside what’s needed to get your order to you — our delivery riders, and the payment provider that processes your transaction.
